import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import manifest from "@/app/manifest";
import { site } from "@/lib/site";

/**
 * Brand files are generated by `scripts/brand-assets.mjs`. These guards catch
 * a config that points at a missing file or states the wrong intrinsic size
 * (which next/image would turn into a stretched or blurry logo).
 */
const publicFile = (src: string) => path.join(process.cwd(), "public", src);

/** Width/height from a PNG's IHDR chunk. */
function pngSize(file: string) {
  const buf = readFileSync(file);
  expect(buf.subarray(1, 4).toString("ascii")).toBe("PNG");
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

describe("brand assets", () => {
  it.each(Object.entries(site.brand))("%s exists with the configured size", (_name, image) => {
    const file = publicFile(image.src);
    expect(existsSync(file)).toBe(true);
    expect(pngSize(file)).toEqual({ width: image.width, height: image.height });
  });

  it("every manifest icon exists and matches its declared size", () => {
    const icons = manifest().icons ?? [];
    expect(icons.some((i) => i.purpose === "maskable")).toBe(true);
    for (const icon of icons) {
      const file = publicFile(icon.src);
      expect(existsSync(file), icon.src).toBe(true);
      const { width, height } = pngSize(file);
      expect(`${width}x${height}`).toBe(icon.sizes);
    }
  });

  it("app icon conventions are present", () => {
    for (const f of ["favicon.ico", "icon.png", "apple-icon.png", "opengraph-image.png", "twitter-image.png"]) {
      expect(existsSync(path.join(process.cwd(), "app", f)), f).toBe(true);
    }
    expect(pngSize(path.join(process.cwd(), "app", "apple-icon.png"))).toEqual({ width: 180, height: 180 });
    expect(pngSize(path.join(process.cwd(), "app", "opengraph-image.png"))).toEqual({ width: 1200, height: 630 });
  });

  it("favicon.ico carries 16, 32 and 48 px images", () => {
    const ico = readFileSync(path.join(process.cwd(), "app", "favicon.ico"));
    const count = ico.readUInt16LE(4);
    const sizes = Array.from({ length: count }, (_, i) => ico.readUInt8(6 + i * 16));
    expect(sizes).toEqual([16, 32, 48]);
  });
});
